await story('A8-15-above-quota-completion',async()=>{
 let a;for(const c of contexts)for(const p of c.pages())if(p.url()===origin+'/ui/hub/admin'&&await p.locator('.hub-row').filter({hasText:'manual'}).getByRole('button',{name:'Approve…',exact:true}).count()){a=p;break;}if(!a)throw Error('exact manual admin pending row missing');
 await a.locator('.hub-row').filter({hasText:'manual'}).getByRole('button',{name:'Approve…',exact:true}).click();await a.locator('.dlg-actions .btn-primary').click();const second=extraPairings.at(-1);await waitFor(()=>second.view().state==='paired','second manual credential pinned');check('manual issuance exceeds automatic max one',true);
 const m=await context(cases[0]);await signIn(m.p,'manual');await m.p.locator('[data-welcome=limit]').waitFor();receipt.manualQuotaText=await m.p.locator('[data-welcome=fleets]').innerText();check('two retained manual fleets count against max one',/2.*1/.test(receipt.manualQuotaText));await shot(m.p,'A8-15-manual-two-of-one');await m.ctx.close();fx.fm.attachHubMemberPairing(globalThis.a8Expiry.ep);
});
const q=await context(cases[0]);await signIn(q.p,'asker',new URL(roomUrl).pathname+new URL(roomUrl).search);await q.p.locator('.hub-chat').waitFor();await new Promise(r=>setTimeout(r,1800));await shot(q.p,'A8-11-revoked-room-final-settled');receipt.finalRevokedRoomText=await q.p.locator('body').innerText();check('final stale room discloses no held answer',!receipt.finalRevokedRoomText.includes('HELD_SECRET_MUST_NOT_APPEAR'));await q.ctx.close();
